INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12093, 12921, 'tt0086373', NULL, 'Strange Brew', 'Strange Brew', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/rScplcvRHX7o7XK88SFb5mddo8y.jpg', 'https://image.tmdb.org/t/p/original/y5yCGyPKS0gk5IOne2y1FYuzJQm.jpg', 'Something is rotten at the Elsinore Brewery. Bob and Doug McKenzie (as seen on SCTV) help the orphan Pam regain the brewery founded by her recently-deceased father. But to do so, they must confront the suspicious Brewmeister Smith and two teams of vicious hockey players.', NULL, NULL, 2.353, 6.022, 0, 9.02, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12094, 110671, 'tt0050771', NULL, 'No Down Payment', 'No Down Payment', 'movie', 1957, 'https://image.tmdb.org/t/p/w500/gjjDmdrkYgZNgNn00QEJE0s5n5i.jpg', 'https://image.tmdb.org/t/p/original/2xegakHz8mB4oVaXSFSSd1nnPT1.jpg', 'The marital difficulties of four couples living in a southern California housing development become intertwined. Among the unhappy couples are ne''er-do-well Jerry Flagg and his long-suffering wife Isabelle, flirtatious Leola Boone and her sadistic husband Troy, hard-working Herman Kreitzer and his understanding wife Betty, and newlyweds Jean and David Martin.', NULL, NULL, 1.6172, 6.3, 0, 7.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12095, 20763, 'tt0105211', NULL, 'Radio Flyer', 'Radio Flyer', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/nQjCKrwWYH6ES0HrnkLkPXnOEp0.jpg', 'https://image.tmdb.org/t/p/original/qupyOOes39BBlCtgvH77vgGVpA1.jpg', 'A father reminisces about his childhood when he and his younger brother moved to a new town with their mother, her new husband and their dog, Shane. When the younger brother is subjected to physical abuse at the hands of their brutal stepfather, Mike decides to convert their toy trolley, the "Radio Flyer", into a plane to fly him to safety.', NULL, NULL, 3.4497, 6.995, 0, 7.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
