INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12097, 27141, 'tt0165859', NULL, 'Liberty Heights', 'Liberty Heights', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/pFcUURqmwvvyq0eFzvDun8daPMX.jpg', 'https://image.tmdb.org/t/p/original/2oOBBTJpkbzW3zOh9JIAWI5vawY.jpg', 'This semi-autobiographical film by Barry Levinson follows various members of the Kurtzman clan, a Jewish family living in suburban Baltimore during the 1950s. As teenaged Ben completes high school, he falls for Sylvia, a black classmate, creating inevitable tensions. Meanwhile, Ben''s brother, Van, attends college and becomes smitten with a mysterious woman while their father tries to maintain his burlesque business.', NULL, NULL, 1.6851, 6.66, 0, 7.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12098, 1516698, 'tt37654096', NULL, 'The Last Sunrise', 'The Last Sunrise', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/pego3yEZ5SuGvRjESKAguL4Wu7M.jpg', 'https://image.tmdb.org/t/p/original/5lB7yPaRhJHQ9dx7AnvPUi0GZDU.jpg', 'Ry, a college student with a chronic illness escapes to Mallorca for the summer with her mother, where she unexpectedly falls for a local and begins to embrace living in the moment. But as her condition worsens and long-hidden family secrets come to light, everything she has found before summer''s end is threatened.', NULL, NULL, 45.9511, 0.0, 0, 8.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12099, NULL, NULL, 7357, 'Parasite Eve', 'Parasite Eve', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4pup.jpg', NULL, 'Parasite Eve is a survival horror role-playing video game developed and published by SquareSoft (now Square Enix) for the Sony PlayStation console. The game follows the story of Aya Brea, a rookie NYPD officer who becomes embroiled in a series of bizarre and deadly events related to a genetic mutation known as mitochondria. The game combines elements of horror, science fiction, and RPG gameplay, featuring real-time battles, exploration, puzzle-solving, and character development. The game''s plot is inspired by the novel of the same name by Hideaki Sena, and its gameplay mechanics were influenced by the Final Fantasy series. Parasite Eve was critically acclaimed upon its release in 1998, and is widely regarded as a classic of the survival horror genre.', 'https://www.igdb.com/games/parasite-eve', '["PlayStation 3", "PlayStation", "PlayStation Portable"]', NULL, NULL, 0, 1.02, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
