INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12102, 36353, 'tt0306097', NULL, 'Stratosphere Girl', 'Stratosphere Girl', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/4qbhiIPBviYUCfugTv1ysSOBZtY.jpg', 'https://image.tmdb.org/t/p/original/wHgsk3A7bgoHyIBwcI3aA75PYhc.jpg', 'Angela is a French art student living in Germany who loves to draw comics and creates elaborate tales drawn in a soft and romantic style. One night, Angela meets Yamamoto, a club DJ from Japan, who invites her to come to Tokyo with him. Infatuated with Yamamoto, Angela impulsively agrees, and is soon sharing an apartment with a handful of Western expatriates who work at a nightclub where Japanese businessmen drink, sing karaoke, and date the "hostesses" for a fee.', NULL, NULL, 2.1711, 5.6, 0, 10.51, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
