INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12110, NULL, NULL, 1030, 'The Legend of Zelda: Majora''s Mask', 'The Legend of Zelda: Majora''s Mask', 'game', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3pah.jpg', NULL, 'The Legend of Zelda: Majora''s Mask is a direct sequel to Ocarina of Time, it utilizes the same engine and visual style as its predecessor. The game retains the traditional elements of Zelda games as well as those introduced in Ocarina of Time, such as active blocking with a shield, various throwing items, and the usage of melodies played on the ocarina to solve puzzles. Compared to the previous Zelda games, this installment is more oriented towards interaction with NPCs and has a larger variety of items, optional quests, and mini-games. It also includes a time system that spans three days, and this cycle must be reset periodically to progress through the game.', 'https://www.igdb.com/games/the-legend-of-zelda-majora-s-mask', '["Wii", "Nintendo 64", "64DD", "Wii U"]', NULL, NULL, 0, 9.58, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
