INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12155, 32631, 'tt0113360', NULL, 'The Hunted', 'The Hunted', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/luCVuKiRBcQjr9MuY9mRCTehjpY.jpg', 'https://image.tmdb.org/t/p/original/hys4aPB77G2pboLRUCWNkl9djbl.jpg', 'Paul Racine, a high-powered American business executive in Japan, is catapulted into a maze of danger and intrigue after he and his sexy companion are the targets of assassins hired by the ruthless Kinjo.  To survive, Racine must join forces with a powerful samurai and together they will fight the force of evil in an awesome battle rooted in centuries of brutal conflict.', NULL, NULL, 4.5476, 5.709, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
