INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12157, 11002, 'tt0087365', NULL, 'Greystoke: The Legend of Tarzan, Lord of the Apes', 'Greystoke: The Legend of Tarzan, Lord of the Apes', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/rdtEIdzqJTVhSLsjuR4U9t1KKxp.jpg', 'https://image.tmdb.org/t/p/original/m7kARS3kMIEFaTtTeSY8w8GHtaF.jpg', 'A shipping disaster in the 19th Century has stranded a man and woman in the wilds of Africa. The lady is pregnant, and gives birth to a son in their tree house. Soon after, a family of apes stumble across the house and in the ensuing panic, both parents are killed. A female ape takes the tiny boy as a replacement for her own dead infant, and raises him as her son. Twenty years later, Captain Phillippe D''Arnot discovers the man who thinks he is an ape. Evidence in the tree house leads him to believe that he is the direct descendant of the Earl of Greystoke, and thus takes it upon himself to return the man to civilization.', NULL, NULL, 4.1429, 6.4, 0, 1.04, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12158, 42455, 'tt0069715', NULL, 'And Now the Screaming Starts!', 'And Now the Screaming Starts!', 'movie', 1973, 'https://image.tmdb.org/t/p/w500/t7qtRYAL9K1g0FAv3QHEvZ12ork.jpg', 'https://image.tmdb.org/t/p/original/c0zsDJV9Xhb4rhzWWzgFEh1S3mO.jpg', 'In the late 18th century, two newlyweds move into the stately mansion of the Fengriffen family. The young bride is victim of terrifying visions and apparitions, threatening her very sanity. A London psychiatrist comes to her help and uncovers the terrible secret that haunts the estate.', NULL, NULL, 1.4121, 5.937, 0, 1.02, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12159, 502167, 'tt6842126', NULL, 'Don''t Leave Home', 'Don''t Leave Home', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/3Y296xLDoTOsts35P3dGErBrZbL.jpg', 'https://image.tmdb.org/t/p/original/vfdkUySTAyjugOJ9LvgDfH3JpWg.jpg', 'An American artist''s obsession with a disturbing urban legend leads her to an investigation of the story''s origins at the crumbling estate of a reclusive painter in Ireland.', NULL, NULL, 1.3948, 4.7, 0, 1.04, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12160, 64684, 'tt3581932', NULL, 'And Then There Were None', 'And Then There Were None', 'tv', 2015, 'https://image.tmdb.org/t/p/w500/xbcGTnlxszacXztaOdY2hu5TI7K.jpg', 'https://image.tmdb.org/t/p/original/iM6t3rNQNmUJgIzNCF1aPiD6A5j.jpg', 'Ten strangers, drawn away from their normal lives to an isolated rock off the Devon coast. But as the mismatched group waits for the arrival of the hosts -- the improbably named Mr. and Mrs. U.N. Owen -- the weather sours and they find themselves cut off from civilization. Very soon, the guests, each struggling with their conscience, will start to die -- one by one, according to the rules of the nursery rhyme ''Ten Little Soldier Boys'' -- a rhyme that hangs in every room of the house and ends with the most terrifying words of all: ''... and then there were none.', NULL, NULL, 8.6955, 7.53, 0, 1.06, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12161, 354743, 'tt4116030', NULL, 'Lady Chatterley''s Lover', 'Lady Chatterley''s Lover', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/6RwYNmcMfsTmOtnNm5PC6LNuy0K.jpg', 'https://image.tmdb.org/t/p/original/txg43Ozkc4X1YGWlmijkipb1Ojq.jpg', 'An early-20th-century tale of love across class boundaries which tells the legendary and romantic story of Lady Chatterley’s affair with her gamekeeper. Jed Mercurio’s adaptation of DH Lawrence’s classic.', NULL, NULL, 4.0415, 6.282, 0, 1.06, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12162, NULL, NULL, 135940, 'Bomb Rush Cyberfunk', 'Bomb Rush Cyberfunk', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ya8.jpg', NULL, 'Bomb Rush Cyberfunk, an indie action-adventure platformer, features 1 second per second of highly advanced funkstyle. In a world where self-styled crews are equipped with personal boostpacks, new heights of graffiti are reached. Start your own cypher and dance, paint, trick, face off with the cops and stake your claim to the extrusions and cavities of a sprawling metropolis in an alternate future.', 'https://www.igdb.com/games/bomb-rush-cyberfunk', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 1.15266666666666672e+01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12163, 19106, 'tt1043852', NULL, 'Round Da Way', 'Lascars', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/myw0jbvci1Z84dMKMtQkCLBaY5u.jpg', 'https://image.tmdb.org/t/p/original/6nUQxbLI0MT44tyuy9CbwrxDg1T.jpg', 'It’s summer in the hood. As every year, there are those who stay, those who leave, and... those who should have left. Some, like Joe Hustleton, work «under the table» in the rich neighborhoods and fall head over heels for a pretty girl. Some, like Tony Pepperoni, play businessman and spend the summer fleeing a local gang leader and a psychopathic girlfriend. Some, like Sammy and Harvey, pretend to have left. Tropics are far for the homies... and summer promises to be very hot!', NULL, NULL, 1.9821, 6.6, 0, 8.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
