INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12188, 296271, 'tt9663168', NULL, 'The Devil Conspiracy', 'The Devil Conspiracy', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/gZCWgbIq2IBDRMJmdx5NeYbbigL.jpg', 'https://image.tmdb.org/t/p/original/sp7MPK2K60LLd7A6zjHKsfgjFil.jpg', 'A powerful biotech company has breakthrough technology allowing them to clone history’s most influential people with just a few fragments of DNA. Behind this company is a cabal of Satanists that steals the shroud of Christ, putting them in possession of Jesus’ DNA. The clone will serve as the ultimate offering to the devil. The Archangel Michael comes to earth and will stop at nothing to end the devil’s conspiracy.', NULL, NULL, 5.8596, 6.438, 0, 7.51, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12189, 337550, 'tt0814106', NULL, 'Flatland', 'Flatland', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/tnJnSSjGiKVBTRbhuJh5wI6Ozy2.jpg', 'https://image.tmdb.org/t/p/original/yw9qfoW8XKAM8pxIlbTqhrHJrFC.jpg', 'Set in a world of only two dimensions inhabited by sentient geometric shapes, the story follows Arthur Square and his ever-curious granddaughter Hex.  When a mysterious visitor arrives from Spaceland, Arthur and Hex must come to terms with the truth of the third dimension, risking dire consequences from the evil Circles that have ruled Flatland for a thousand years.', NULL, NULL, 3.2035, 5.8, 0, 9.53, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12190, 65504, 'tt0262333', NULL, 'Chronopolis', 'Chronopolis', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/9An9FKnD3vUTQU5cZtzKOFBejhk.jpg', 'https://image.tmdb.org/t/p/original/ddVYvhfNBI2vBRXpamsECpSvVKl.jpg', 'In a gargantuan city lurking in the sky, powerful immortals who have become jaded with eternal life. Most of their time is spent monotonously constructing bizarre and unusual objects while waiting for the ultimate gift to arrive.', NULL, NULL, 1.8044, 6.0, 0, 8.51, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12191, 19065, 'tt0102729', NULL, 'Pure Luck', 'Pure Luck', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/3ZFbRfsSa04TTHzqcEFZtk6YYPe.jpg', 'https://image.tmdb.org/t/p/original/c6DUP4WP18Ei5nUZK6EfNDiFKoy.jpg', 'The daughter of a wealthy businessman has disappeared in Mexico, and all the efforts to find her have been unsuccessful. A psychologist, knowing that the girl has an ultra bad luck, persuades her father to send to Mexico one of his employees, an accountant with super bad luck, to find her. Perhaps he will be lucky, and his bad luck could help to find the unlucky girl.', NULL, NULL, 2.7728, 5.6, 0, 8.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12192, 47425, 'tt0178109', NULL, 'Witch''s Cradle', 'Witch''s Cradle', 'movie', 1944, 'https://image.tmdb.org/t/p/w500/uN6XtnX0L8tC2WkvbqMhcz4RE3r.jpg', 'https://image.tmdb.org/t/p/original/sGf2w0AtxFE3j3yqCyMM6bUrzmC.jpg', 'The surrealist film shows repetitive imagery involving a string fashioned in a bizarre, almost spiderweb-like pattern over the hands of several individuals, most notably an unnamed young woman and an elderly gentleman. The film also shows a shadowy darkness and people filmed at odd angles, an exposed human heart, and other occult symbols and ritualistic imagery which evokes an unsettling and dream-like aura. Considered an unfinished film.', NULL, NULL, 0.8948, 6.727, 0, 1.06, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
