INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12196, 531454, 'tt8580274', NULL, 'Eurovision Song Contest: The Story of Fire Saga', 'Eurovision Song Contest: The Story of Fire Saga', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/9zrbgYyFvwH8sy5mv9eT25xsAzL.jpg', 'https://image.tmdb.org/t/p/original/jMO1icztaUUEUApdAQx0cZOt7b8.jpg', 'Two small-town singers chase their pop star dreams at a global music competition, where high stakes, scheming rivals and onstage mishaps test their bond.', NULL, NULL, 3.9514, 6.404, 0, 4.395, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12197, 1720, 'tt0351461', NULL, 'Noi the Albino', 'Nói albínói', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/dy8srjJ3pQCA967wcJ2WaaTbr51.jpg', 'https://image.tmdb.org/t/p/original/2verdecl3RVgi25DCi9LgynSJtF.jpg', '17 year old Nói drifts through life on a remote fjord in Iceland. In winter, the fjord is cut off from the outside world, surrounded by ominous mountains and buried under a shroud of snow. Nói dreams of escaping from this white-walled prison with Íris, a city girl who works in a local gas station. But his clumsy attempts at escape spiral out of control.', NULL, NULL, 1.2454, 7.0, 0, 1.03, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12198, 42770, 'tt0116116', NULL, 'Devil''s Island', 'Djöflaeyjan', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/2A7k8Czmf7K4RufwavD4SI420tO.jpg', 'https://image.tmdb.org/t/p/original/bi03UdbSAHF1jxjKbLUDDO9Dmky.jpg', 'Devil''s Island is a bitter sweet tale of Iceland in the fifties. Life is rough in Reykjavik''s post-war slum of Camp Thule, where the abandoned US military barracks have been turned into makeshift homes. Struggling wives and their hard-working husbands try to make ends meet. The younger generation dreams of dollars, Rock''n''Roll and the American way of life. To celebrate or to drown their misery - they''re never short of a good reason to booze. Devil''s Island vividly depicts the everyday life of a wacky family, their neighbours and friends and shows how some of their dreams come true and others don''t.', NULL, NULL, 0.8943, 6.6, 0, 1.03, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
