INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12237, 63590, 'tt0082527', NULL, 'Hospital Massacre', 'Hospital Massacre', 'movie', 1981, 'https://image.tmdb.org/t/p/w500/1ScSFs8uJA42eI5acIEo8n7YaDE.jpg', 'https://image.tmdb.org/t/p/original/gCaWMc8uFZHkqfYXAbWwk9qDl7a.jpg', 'When Susan was a little girl, she rejected the Valentine of a lovestruck classmate. Decades later, she’s come to the hospital for a routine medical examination, and finds herself trapped in a bizarre nightmare, made all the worse as her vengeful childhood valentine, disguised among the hospital staff, begins murdering everyone in his path as a means of proving his undying ‘romantic’ obsession…', NULL, NULL, 1.5832, 5.197, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12238, 15095, 'tt3694654', NULL, 'To Catch a Predator', 'To Catch a Predator', 'tv', 2004, 'https://image.tmdb.org/t/p/w500/3Kp8JjjsWDlEvPXvp7LjLIyjGt2.jpg', 'https://image.tmdb.org/t/p/original/xIMpZ62EnB8pZsOP23XhydUY7Eb.jpg', 'To Catch a Predator is an American reality television series that features hidden camera investigations by the television newsmagazine program Dateline NBC. It was devoted to impersonating underage people and detaining male adults who contacted them over the Internet for sexual liaisons. People were lured to meet with a decoy under the pretense of sexual contact and then confronted. Show host Chris Hansen clarified in an interview with NPR News that these subjects should be labeled as potential sexual predators, and not pedophiles. "Pedophiles have a very specific definition, people who are interested in prepubescent sex," he stated.

The series premiered in November 2004, and featured 12 investigations in total held across the United States. The investigations were conducted as undercover sting operations with the help of on-line watchdog group Perverted-Justice. Since the third installment, law enforcement and other officials were also involved, leading to the arrests of most individuals caught. No new episodes have aired since December 2007.

NBC affiliates WTMJ in Milwaukee, KSHB in Kansas City and WBRE have also done local versions of To Catch a Predator. Various spin-offs have aired in the same format, including To Catch a Con Man, To Catch an ID Thief, To Catch a Car Thief and To Catch an i-Jacker, which featured iPod thieves. To Catch a Predator is also aired on FX and Crime & Investigation Network in the United Kingdom, the Crime & Investigation Network in Australia and New Zealand and FOX Crime in Portugal.', NULL, NULL, 3.0269, 7.0, 0, 6.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12239, 16072, 'tt0259127', NULL, 'Attila', 'Attila', 'tv', 2001, 'https://image.tmdb.org/t/p/w500/e8sSkLQ9CMH9nckLk5RSc0gxOfh.jpg', 'https://image.tmdb.org/t/p/original/5ZLiwDymzKaNtLMOJCN2YkAE7E0.jpg', 'Attila was an American TV miniseries set during the waning days of the Western Roman Empire, in particular during the invasions of the Huns in Europe.', NULL, NULL, 4.3518, 6.3, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12240, 10644, 'tt0096332', NULL, 'The Unbearable Lightness of Being', 'The Unbearable Lightness of Being', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/g1kPEwATsCI8DnGx6ViAhUVKQSI.jpg', 'https://image.tmdb.org/t/p/original/wru4lC7aK4BYJzxAOoDI0vlfXL7.jpg', 'Successful surgeon Tomas leaves Prague for an operation, meets a young photographer named Tereza, and brings her back with him. Tereza is surprised to learn that Tomas is already having an affair with the bohemian Sabina, but when the Soviet invasion occurs, all three flee to Switzerland. Sabina begins an affair, Tom continues womanizing, and Tereza, disgusted, returns to Czechoslovakia. Realizing his mistake, Tomas decides to chase after her.', NULL, NULL, 4.7684, 6.834, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12241, 480736, 'tt7225386', NULL, '25 km/h', '25 km/h', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/gux7726i4VdKCGZFyeN6lL4Rvr3.jpg', 'https://image.tmdb.org/t/p/original/UVAmU63ORkBRVtUuT3HK0EP1BU.jpg', 'A road movie about two very different brothers who have not seen each other for 20 years: city manager Christian  and cabinetmaker Georg, who never left their hometown and took care of their father until his passing.  After their fathers funeral, the brothers decide on a whim, and with some help from the alcohol, to fulfil their old dream: travel trough Germany together on their mopeds.', NULL, NULL, 1.685, 6.847, 0, 9.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12242, 650272, 'tt11161374', NULL, 'Beyond the Law', 'Beyond the Law', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/3yIhZPJuoo0LATK9TxVhxmQWGy3.jpg', 'https://image.tmdb.org/t/p/original/AopMTry2Pt1nyQGRv7gGlmPQeiu.jpg', 'When a former detective learns of the murder of his estranged son, he ventures back to the darkened streets he once knew so well. Armed, dangerous and with nothing to lose, he must take on the ruthless local mob in his mission for revenge.', NULL, NULL, 3.1298, 5.212, 0, 9.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12243, 42598, 'tt0066286', NULL, 'Rebel Rousers', 'Rebel Rousers', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/w9aOvcN09KRNDmsuHEYS00Td285.jpg', 'https://image.tmdb.org/t/p/original/hID33kEp3Vl6zdHtkuaCgCDmJPv.jpg', 'In a small, US costal town with many Spanish speakers, a motorcycle gang arrives on holiday. Also in town to try to reconnect with his pregnant girlfriend, Karen, is businessman Paul Collier. Paul and a leader of the cyclists, J.J., knew each other years before, so when the gang comes upon the couple and, led by the menacing Bunny, beats up Paul and begins a sexual assault of Karen, J.J. tries to intervene: he suggests they hold cycle-riding contests, with the winner claiming Karen (he promises, sotto voce, to set her free if he wins). After the contests commence, Paul crawls away to look for help. He meets with a shrug from a cowardly sheriff''s deputy; where can he turn?', NULL, NULL, 1.219, 4.2, 0, 9.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12244, 33642, 'tt0061758', NULL, 'Hells Angels on Wheels', 'Hells Angels on Wheels', 'movie', 1967, 'https://image.tmdb.org/t/p/w500/8fj3UEgROOWRyyJEnCdo8nUsyFV.jpg', 'https://image.tmdb.org/t/p/original/xDxPHGqcfI3iCJ9zDW1wsI67D6I.jpg', 'At first gas station attendant Poet is happy when the rockers gang “Hell’s Angels” finally accepts him. But he’s shocked when he learns how brutal they are – not even murder is a taboo to them. He gets himself in trouble when the leader’s girlfriend falls in love with him – and he welcomes her approaches.', NULL, NULL, 1.9571, 5.233, 0, 9.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
