INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12251, 66402, 'tt5547946', NULL, 'Ride with Norman Reedus', 'Ride with Norman Reedus', 'tv', 2016, 'https://image.tmdb.org/t/p/w500/dQyDwNVO88PK2l8rQLaGR2mW6od.jpg', 'https://image.tmdb.org/t/p/original/oKzXzbRIVfTVQ4z5pyAdLhnq97o.jpg', 'The Walking Dead star and motorcycle enthusiast Norman Reedus hits the open road to explore local biker culture and celebrate the best and brightest collectors, mechanics and craftsmen around the country. Each episode features Reedus and a riding companion – a fellow actor, musician, friend or local chopper fanatic – as they journey to custom bike shops, tattoo parlors, collector’s warehouses, or a roadside smokehouse… with plenty of time for unplanned detours and tire changes.', NULL, NULL, 7.3731, 7.4, 0, 9.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
