INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12254, 3920, 'tt0413542', NULL, 'Biker Build-Off', 'Biker Build-Off', 'tv', 2002, 'https://image.tmdb.org/t/p/w500/xgilLKHHpcEzQHXW7SQrFiPxRvm.jpg', NULL, 'Biker Build-Off is a reality television series for the Discovery Channel. Created and narrated by Thom Beers, the series was originally conceived as a single special called The Great Biker Build-Off. The show proved so popular that more episodes were produced in succeeding years, to the point that it was turned into a regular series in 2005.', NULL, NULL, 2.9139, 9.0, 0, 8.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
