INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12256, 1376457, 'tt39075020', NULL, 'Soumsoum, the Night of the Stars', 'Soumsoum, la nuit des astres', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/kF9sOJYIiydmASe9goYz8c7Zgpn.jpg', 'https://image.tmdb.org/t/p/original/2gwrEpV0YZI73nLjPD6E9urdHz.jpg', 'Seventeen-year-old Kellou has been gifted with supernatural powers she does not understand. Her disquiet and uncertainty only change when she meets Aya. It is an encounter with destiny that forges a mystical world where the visible and invisible converge.', NULL, NULL, 3.8875, 7.5, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12257, 1013865, 'tt6315898', NULL, 'Mami Wata', 'Mami Wata', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/uiYCfBmoY7c5m19Jhtbjxu5l1Ed.jpg', 'https://image.tmdb.org/t/p/original/ycyssTVBW4x1DLapPcUfluCXsM1.jpg', 'In the oceanside village of Iyi, the revered Mama Efe acts as an intermediary between the people and the all-powerful water deity Mami Wata. But when a young boy is lost to a virus, Efe’s devoted but rebellious daughter Zinwe and skeptical protégé Prisca warn Efe about unrest among the villagers. With the sudden arrival of a mysterious rebel deserter named Jasper, a conflict erupts, leading to a violent clash of ideologies and a crisis of faith for the people of Iyi.', NULL, NULL, 2.0503, 5.536, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12258, 75491, 'tt1355638', NULL, 'The Rabbi''s Cat', 'Le Chat du rabbin', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/pcjwhq6hF3z2Wir0ZcKHTxmtRsH.jpg', 'https://image.tmdb.org/t/p/original/obtBUwnhRO8qcjCSB9iGvN9CCWz.jpg', 'The story of a rabbi and his talking cat, a sharp-tongued feline philosopher brimming with scathing humor and a less than pure love for the rabbi''s teenage daughter.', NULL, NULL, 2.0049, 7.018, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12259, 28005, 'tt0116743', NULL, 'Kama Sutra: A Tale of Love', 'Kama Sutra: A Tale of Love', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/kUaWgLrI7HqpPqPxgR54wSGokCV.jpg', 'https://image.tmdb.org/t/p/original/gftDU03xnFig2yrNYrNFPCBMQZC.jpg', 'Tara and Maya are inseparable, with the same tastes, habits, and hobbies. Years later, the two have matured but have maintained their friendship. Tara marries local prince Raj Singh, who succeeds the throne as the sole heir. After the marriage, Raj seeks another female to satisfy his sexual desires, with his sights settling on Maya, putting a perhaps unforgivable strain on a longtime friendship.', NULL, NULL, 3.5962, 5.723, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12260, 4822, 'tt0048260', NULL, 'Kismet', 'Kismet', 'movie', 1955, 'https://image.tmdb.org/t/p/w500/pqFy36jp7aDXA6EIzGpz61r7tDL.jpg', 'https://image.tmdb.org/t/p/original/UkiaWUABkxr51jUpp35MvLb8v4.jpg', 'A silver-tongued poet and self-proclaimed "King of the Beggars" searches old Baghdad for a rich bachelor to marry his dreamy daughter, Marsinah. Along the way, he poses as the renowned sorcerer Hajj and gets in and out of scrapes with an elderly thief, a dim-witted wazir, and his wife. Meanwhile, his daughter develops feelings for a handsome caliph.', NULL, NULL, 1.1385, 5.583, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12261, 93685, 'tt0284534', NULL, 'Swingers', 'Swingers', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/cEIVkvx6mGSjnkOxlXh6eHd1Y4K.jpg', 'https://image.tmdb.org/t/p/original/mysDkqI25jW2qpbm44IB8qQyfYv.jpg', 'Despite Diana''s insecure nature, she and her husband Julian agree with the idea to sexually experiment with another couple. They put out an ad on the net to which the well experienced Alex and Timo react. We follow Diana and Julian as they prepare for the arrival of Alex and Timo, who they have invited to their home for the weekend. Diana is nervous. As soon as she is confronted with the self-confident and ravishingly sexy Alex, her insecurity increases even more. Timo seems disinterested, a sharp contrast to the boyish excitement of Julian. But as night falls and their sexual exploration begins, we notice Timo may not be as casual as he initially seemed and Diana on the other hand contains hidden strength. And so we realize there''s more to ''Swingers'' than just sex. Swingers: could your relationship stand the test?', NULL, NULL, 8.3247, 5.974, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12262, 103332, 'tt1839492', NULL, 'Ruby Sparks', 'Ruby Sparks', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/zELurt0GVRkR5X5ymuk7KXUxhC8.jpg', 'https://image.tmdb.org/t/p/original/4EqTcyWfO807ihMzGHequR7x1Co.jpg', 'Calvin is a young novelist who achieved phenomenal success early in his career but is now struggling with his writing – as well as his romantic life. Finally, he makes a breakthrough and creates a character named Ruby who inspires him. When Calvin finds Ruby, in the flesh, sitting on his couch about a week later, he is completely flabbergasted that his words have turned into a living, breathing person.', NULL, NULL, 5.3106, 7.108, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12263, 83116, 'tt0042285', NULL, 'Bright Leaf', 'Bright Leaf', 'movie', 1950, 'https://image.tmdb.org/t/p/w500/3zNlVaHbobs4sfo0xK77R15oJJ.jpg', 'https://image.tmdb.org/t/p/original/o4m8u90LyJrFCC4ZEHQ4zbTVeCD.jpg', 'Two tobacco growers battle for control of the cigarette market.', NULL, NULL, 1.3857, 5.976, 0, 11.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
