INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12265, 3111, 'tt0047522', NULL, 'A Star Is Born', 'A Star Is Born', 'movie', 1954, 'https://image.tmdb.org/t/p/w500/zpg2SzpYhZk1D1seDfIIlwaqAxT.jpg', 'https://image.tmdb.org/t/p/original/AlvKqnxlkWWYE6ngRLOWfYY3QuI.jpg', 'A movie star helps a young singer-actress find fame, even as age and alcoholism send his own career into a downward spiral.', NULL, NULL, 2.9475, 7.135, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12266, 1267217, 'tt30225465', NULL, 'Sugar Baby', 'Почему ты?', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/kcREsnVDEFFXmt5GuPwyGqyDuDJ.jpg', 'https://image.tmdb.org/t/p/original/gscL9tqxpkmAMmbeRLLzLZPyJXb.jpg', 'Love comes without asking. Often not to those, not so and not then. Can a genuine feeling survive when everything started wrong and the whole world is against it? Give up everything or give up? Burn or survive?', NULL, NULL, 5.1769, 7.0, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12267, 7350, 'tt0825232', NULL, 'The Bucket List', 'The Bucket List', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/idbNSe8zsYKQL97dJApfOrDSdya.jpg', 'https://image.tmdb.org/t/p/original/6OpluXPGIE8hfVrhpeygR7p4XwR.jpg', 'Corporate billionaire Edward Cole and working class mechanic Carter Chambers are worlds apart. At a crossroads in their lives, they share a hospital room and discover they have two things in common: a desire to spend the time they have left doing everything they ever wanted to do and an unrealized need to come to terms with who they are. Together they embark on the road trip of a lifetime, becoming friends along the way and learning to live life to the fullest, with insight and humor.', NULL, NULL, 7.1144, 7.187, 0, 1.01, '2026-08-26 01:43:46', '2026-08-26 01:43:46');
