UPDATE "recommendations" SET "tmdb_id"=6114, "imdb_id"='tt0103874', "igdb_id"=NULL, "title"='Bram Stoker''s Dracula', "original_title"='Bram Stoker''s Dracula', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/jSxCIZXudp5q8wQO8VERGX8hRAl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/88S6EYQBVyQktDfSqsB33I169jN.jpg', "overview"='Count Dracula, a 15th-century prince, is condemned to live off the blood of the living for eternity. Young lawyer Jonathan Harker is sent to Dracula''s castle to finalise a land deal, but when the Count sees a photo of Harker''s fiancée, Mina, the spitting image of his dead wife, he imprisons him and sets off for London to track her down.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.4789, "vote_average"=7.448, "is_ambiguous"=0, "evidence_score"=6.0953684210526319e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-26 01:43:46' WHERE "id"=1;
