UPDATE "recommendations" SET "tmdb_id"=120, "imdb_id"='tt0120737', "igdb_id"=NULL, "title"='The Lord of the Rings: The Fellowship of the Ring', "original_title"='The Lord of the Rings: The Fellowship of the Ring', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mWDdRXTivGE7aaY2vo1Ie0PfCX5.jpg', "overview"='Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.', "external_url"=NULL, "platforms"=NULL, "popularity"=47.6819, "vote_average"=8.439, "is_ambiguous"=0, "evidence_score"=7.59167605633802793e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-26 01:43:46' WHERE "id"=5;
