UPDATE "recommendations" SET "tmdb_id"=75612, "imdb_id"='tt1483013', "igdb_id"=NULL, "title"='Oblivion', "original_title"='Oblivion', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/bYLM3GpNUZnoFElPXp1zlhDPdtv.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2kVt8oj1cSz4GAP0Hi8SESOiH0T.jpg', "overview"='Jack Harper is one of the last few drone repairmen stationed on Earth. Part of a massive operation to extract vital resources after decades of war with a terrifying threat known as the Scavs, Jack’s mission is nearly complete. His existence is brought crashing down when he rescues a beautiful  stranger from a downed spacecraft. Her arrival triggers a chain of events that  forces him to question everything he knows and puts the fate of humanity in his hands.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.7316, "vote_average"=6.686, "is_ambiguous"=0, "evidence_score"=3.24052173913043475e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-26 01:43:46' WHERE "id"=35;
UPDATE "recommendations" SET "tmdb_id"=274854, "imdb_id"='tt1618442', "igdb_id"=NULL, "title"='The Last Witch Hunter', "original_title"='The Last Witch Hunter', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/dS9YdnJkxtKE2PKCSsxTaO7Jpf5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mXmvN6drkdU1PWFF92AGklEVIa3.jpg', "overview"='The modern world holds many secrets, but by far the most astounding is that witches still live among us; vicious supernatural creatures intent on unleashing the Black Death upon the world and putting an end to the human race once and for all. Armies of witch hunters have battled this unnatural enemy for centuries, including Kaulder, a valiant warrior who many years ago slayed the all-powerful Witch Queen, decimating her followers in the process. In the moments right before her death, the Queen cursed Kaulder with immortality, forever separating him from his beloved wife and daughter. Today, Kaulder is the last living hunter who has spent his immortal life tracking down rogue witches, all the while yearning for his long-lost family.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.6492, "vote_average"=6.017, "is_ambiguous"=0, "evidence_score"=7.66454166666666623e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-26 01:43:46' WHERE "id"=39;
