UPDATE "recommendations" SET "tmdb_id"=50014, "imdb_id"='tt1454029', "igdb_id"=NULL, "title"='The Help', "original_title"='The Help', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/3kmfoWWEc9Vtyuaf9v5VipRgdjx.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/wyvUmyzqGOBDyqLHRSukGDjI7bH.jpg', "overview"='Aibileen Clark is a middle-aged African-American maid who has spent her life raising white children and has recently lost her only son; Minny Jackson is an African-American maid who has often offended her employers despite her family''s struggles with money and her desperate need for jobs; and Eugenia "Skeeter" Phelan is a young white woman who has recently moved back home after graduating college to find out her childhood maid has mysteriously disappeared. These three stories intertwine to explain how life in Jackson, Mississippi revolves around "the help"; yet they are always kept at a certain distance because of racial lines.', "external_url"=NULL, "platforms"=NULL, "popularity"=14.0301, "vote_average"=8.204, "is_ambiguous"=0, "evidence_score"=6.01333333333333364e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-26 01:43:46' WHERE "id"=2930;
