UPDATE "recommendations" SET "tmdb_id"=1408493, "imdb_id"='tt35692176', "igdb_id"=NULL, "title"='The Turkish Coffee Table', "original_title"='Cam Sehpa', "media_type"='movie', "release_year"=2026, "poster_url"='https://image.tmdb.org/t/p/w500/keGMCONOSK0omAk1uMdilSftePd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nUMxXcgdQOtphcObnIbokw7dRZU.jpg', "overview"='When Zehra and İbrahim, a couple adjusting to new parenthood, argue over a coffee table, it seems like a harmless domestic spat. Wanting to assert himself for once, İbrahim insists on buying it. But when he’s left alone to assemble it, he makes a single irreversible mistake — and begins spiraling into a pit of lies, panic, and performative calm as he tries to hide the truth from the people he loves the most.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.908, "vote_average"=6.5, "is_ambiguous"=0, "evidence_score"=9.29875, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-26 01:43:46' WHERE "id"=6700;
