UPDATE "recommendations" SET "tmdb_id"=19120, "imdb_id"='tt0059229', "igdb_id"=NULL, "title"='Juliet of the Spirits', "original_title"='Giulietta degli spiriti', "media_type"='movie', "release_year"=1965, "poster_url"='https://image.tmdb.org/t/p/w500/NbN10moPWQiiIKDJsC7A3j4Mcy.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9VeXz4mj4QaOfTNSLy0owJHkWEo.jpg', "overview"='Middle-aged Giulietta grows suspicious of her husband, Giorgio, when his behavior grows increasingly questionable. One night when Giorgio initiates a seance amongst his friends, Giulietta gets in touch with spirits and learns more about herself and her painful past. Slightly skeptical, but intrigued, she visits a mystic who gives her more information -- and nudges her toward the realization that her husband is indeed a philanderer.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.4379, "vote_average"=7.21, "is_ambiguous"=0, "evidence_score"=9.08, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-26 01:43:46' WHERE "id"=6715;
