UPDATE "recommendations" SET "tmdb_id"=41613, "imdb_id"='tt0337585', "igdb_id"=NULL, "title"='Bomb the System', "original_title"='Bomb the System', "media_type"='movie', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/r4wOlMjNTcCYLXX7Nzd3G6ECyFM.jpg', "backdrop_url"=NULL, "overview"='Anthony ‘Blest’ (Mark Webber) is one of the most talented and notorious graffiti artists in New York City. Despite the tragic loss of his older brother during a nightly ''bombing'' foray with a graffiti crew, Anthony has the same insatiable addiction. With the other members of his ‘crew,’ Anthony parties, shoplifts spray-paint and ''tags'' virgin walls with his signature ''Blest.'' He does his best to avoid run-ins with the cops and hostile rival crews, but he can’t avoid the pressure from his mother to attend college, and from his girlfriend to leave New York with her. As tensions rise, a physical threat from the cops causes the crew to intensify their bombing excursions, calling an all out war on the city. When the inevitable confrontation happens, a tragedy results that pushes Anthony to make a decision that has even darker consequences.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.5742, "vote_average"=7.0, "is_ambiguous"=0, "evidence_score"=5.34666666666666579e+00, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-26 01:43:46' WHERE "id"=6788;
