UPDATE "recommendations" SET "tmdb_id"=29845, "imdb_id"='tt0072417', "igdb_id"=NULL, "title"='A Woman Under the Influence', "original_title"='A Woman Under the Influence', "media_type"='movie', "release_year"=1974, "poster_url"='https://image.tmdb.org/t/p/w500/6EJ4JoTxnH1QmGTE9pPzgtW1cLW.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uOLcJJYZ3hbFSrKQPDaLhrYnjUv.jpg', "overview"='Mabel Longhetti, desperate and lonely, is married to a Los Angeles municipal construction worker, Nick. Increasingly unstable, especially in the company of others, she craves happiness, but her extremely volatile behavior convinces Nick that she poses a danger to their family and decides to commit her to an institution for six months. Alone with a trio of kids to raise on his own, he awaits her return, which holds more than a few surprises.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.9931, "vote_average"=7.784, "is_ambiguous"=0, "evidence_score"=9.49, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-26 01:43:46' WHERE "id"=8666;
