UPDATE "recommendations" SET "tmdb_id"=41852, "imdb_id"='tt0116275', "igdb_id"=NULL, "title"='A Family Thing', "original_title"='A Family Thing', "media_type"='movie', "release_year"=1996, "poster_url"='https://image.tmdb.org/t/p/w500/1IHxwmguaeytGo6m0wZaS0s3fP.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ypjHHnZuPn7A1Euqi1onU32Ejgs.jpg', "overview"='Earl Pilcher Jr. runs an equipment rental outfit in Arkansas, lives with his wife and kids and parents, and rarely takes off his gimme cap. His mother dies, leaving a letter explaining he''s not her natural son, but the son of a Black woman who died in childbirth; plus, he has a half brother Ray, in Chicago, she wants him to visit. Earl makes the trip, initially receiving a cold welcome from Ray and Ray''s son, Virgil. His birth mother''s sister, Aunt T., an aged and blind matriarch, takes Earl in tow and insists that the family open up to him.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8736, "vote_average"=6.558, "is_ambiguous"=0, "evidence_score"=22.03, "created_at"='2026-08-11 02:46:38', "updated_at"='2026-08-26 01:43:46' WHERE "id"=9222;
