UPDATE "recommendations" SET "tmdb_id"=939428, "imdb_id"=NULL, "igdb_id"=NULL, "title"='The Night Is Short, Walk On Girl', "original_title"='夜は短し歩けよ乙女', "media_type"='movie', "release_year"=2021, "poster_url"='https://image.tmdb.org/t/p/w500/7ZO4UX0qKVFQvPiyjUks3iidbyv.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/yrPHWIAiiBF3pLGFasWQbjdD9W0.jpg', "overview"='The best-selling "The Night Is Short, Walk on Girl" novel is a story set in Kyoto about a “Senpai” who has a crush on “The Girl with Black Hair”, his junior, and depicts how he gets caught up in various incidents by trying to draw her attention. Adopting the novel for this theatre play, Makoto Ueda, representative of popular theatre company "Europe Kikaku" based mainly in Kyoto, is leading as scriptwriter and director.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.7974, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=5.26, "created_at"='2026-08-22 01:37:44', "updated_at"='2026-08-26 01:43:46' WHERE "id"=11307;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=2853, "title"='Braid', "original_title"='Braid', "media_type"='game', "release_year"=2008, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co25ni.jpg', "backdrop_url"=NULL, "overview"='Braid is a puzzle-platformer, drawn in a painterly style, where you can manipulate the flow of time in strange and unusual ways. From a house in the city, journey to a series of worlds and solve puzzles to rescue an abducted princess. In each world, you have a different power to affect the way time behaves, and it is time''s strangeness that creates the puzzles. The time behaviors include: the ability to rewind, objects that are immune to being rewound, time that is tied to space, parallel realities, time dilation, and perhaps more.

Braid treats your time and attention as precious; there is no filler in this game. Every puzzle shows you something new and interesting about the game world.', "external_url"='https://www.igdb.com/games/braid', "platforms"='["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=6.51, "created_at"='2026-08-22 01:37:44', "updated_at"='2026-08-26 01:43:46' WHERE "id"=11321;
